	public static AnimationDefinition of(MinosAnim anim) {
		return switch (anim) {
			case IDLE -> IDLE;
			case INTRO -> INTRO;
			case STRIKE -> STRIKE;
			case TAIL -> TAIL;
			case SENTENCE -> SENTENCE;
			case GRAB -> GRAB;
			case HOLD -> HOLD;
			case RELEASE -> RELEASE;
			case STAGGER -> STAGGER;
			case PHASE -> PHASE;
			case HURT -> HURT;
			case DEATH -> DEATH;
		};
	}

	/** Every animation, in MinosAnim's order. */
	public static List<AnimationDefinition> all() {
		return Arrays.stream(MinosAnim.values()).map(MinosAnimations::of).toList();
	}
